<?php require __DIR__ . '/layout.php'; admin_layout_start('用户管理', 'users'); ?>
<div class="card"><div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:#F1F5F9"><th style="padding:10px 14px;text-align:left;font-weight:600;color:#6B7280;font-size:12px">ID</th><th style="padding:10px 14px;text-align:left;font-weight:600;color:#6B7280;font-size:12px">用户名</th><th style="padding:10px 14px;text-align:left;font-weight:600;color:#6B7280;font-size:12px">邮箱</th><th style="padding:10px 14px;text-align:left;font-weight:600;color:#6B7280;font-size:12px">认证</th><th style="padding:10px 14px;text-align:left;font-weight:600;color:#6B7280;font-size:12px">状态</th><th style="padding:10px 14px;text-align:left;font-weight:600;color:#6B7280;font-size:12px">最后登录</th><th style="padding:10px 14px;text-align:left;font-weight:600;color:#6B7280;font-size:12px">操作</th></tr></thead><tbody id="tbody"><tr><td colspan="7" style="text-align:center;padding:30px;color:#9CA3AF">加载中...</td></tr></tbody></table></div><div id="pager" style="display:flex;align-items:center;justify-content:center;gap:12px;margin-top:20px;font-size:13px"></div></div>
<script>
var page=1;
async function load(p){page=p||1;try{var r=await axios.post('/admin/users/list',{page:page});if(r.data.code===200){var list=r.data.data.list,total=r.data.data.total,limit=20,h='';if(list.length===0)h='<tr><td colspan="7" style="text-align:center;padding:30px;color:#9CA3AF">暂无用户</td></tr>';else list.forEach(function(u){h+='<tr style="border-bottom:1px solid #E2E8F0"><td style="padding:10px 14px">'+u.id+'</td><td style="padding:10px 14px">'+u.username+'</td><td style="padding:10px 14px">'+(u.email||'-')+'</td><td style="padding:10px 14px"><span style="padding:2px 10px;border-radius:99px;font-size:11px;font-weight:500;background:'+(u.certify_status?'#D1FAE5;color:#10B981':'#F1F5F9;color:#6B7280')+'">'+(u.certify_status?'已认证':'未认证')+'</span></td><td style="padding:10px 14px"><span style="padding:2px 10px;border-radius:99px;font-size:11px;font-weight:500;background:'+(u.status?'#D1FAE5;color:#10B981':'#FEE2E2;color:#EF4444')+'">'+(u.status?'正常':'禁用')+'</span></td><td style="padding:10px 14px;font-size:12px">'+(u.last_login_time||'-')+'</td><td style="padding:10px 14px"><a href="javascript:void(0)" onclick="toggle('+u.id+','+(u.status?0:1)+')" style="color:'+(u.status?'#EF4444':'#10B981')+';font-size:12px;text-decoration:none">'+(u.status?'禁用':'启用')+'</a></td></tr>'});document.getElementById('tbody').innerHTML=h;var ph='';if(page>1)ph+='<a href="javascript:load('+(page-1)+')" style="padding:6px 12px;border:1px solid #E2E8F0;border-radius:6px;text-decoration:none;color:#6B7280;font-size:12px">上一页</a>';ph+='<span style="color:#6B7280">第 '+page+' 页 ('+total+' 条)</span>';if(page*limit<total)ph+='<a href="javascript:load('+(page+1)+')" style="padding:6px 12px;border:1px solid #E2E8F0;border-radius:6px;text-decoration:none;color:#6B7280;font-size:12px">下一页</a>';document.getElementById('pager').innerHTML=ph;}}catch(e){}}
async function toggle(id,status){try{await axios.post('/admin/users/toggle',{id:id,status:status});load(page)}catch(e){alert('操作失败')}}
load(1);
</script>
<?php admin_layout_end(); ?>